from __future__ import annotations


def _checkpoint(prompt, options, correct_index, explanation):
    return {"prompt": prompt, "options": tuple(options), "correct_index": correct_index, "explanation": explanation}


def _project_runtime(day):
    special = {
        21: ("day_21_project.sql", "sqlite3 app.db < day_21_project.sql"),
        22: ("index.html", "Откройте index.html в браузере"),
        28: ("shans.service", "sudo systemctl enable --now shans.service"),
        29: ("Dockerfile", "docker build -t shans-app ."),
    }
    return special.get(day, (f"day_{day:02d}_project.py", f"python day_{day:02d}_project.py"))


def _lesson(day, title, summary, terms, practice, code, question, answers, correct, explanation):
    concept_text = "; ".join(f"{term} — {definition}" for term, definition in terms)
    project_file, run_command = _project_runtime(day)
    return {
        "day": day,
        "title": title,
        "summary": summary,
        "lecture": (
            f"Главная задача дня — {summary.lower()} Сначала поймите назначение инструмента, затем проследите данные от входа до результата и только после этого запоминайте синтаксис.",
            f"Ключевые понятия: {concept_text}. Связывайте каждое понятие с конкретной строкой программы, а не с абстрактным определением.",
            f"Бытовая модель: программа похожа на понятную инструкцию для исполнителя. В теме «{title}» важно назвать входные данные, последовательность действий, возможную ошибку и ожидаемый результат.",
        ),
        "terms": tuple(terms),
        "practice": practice,
        "presentation_file": f"presentations/python-basics/python_day{day:02d}_simple_readable.pdf",
        "cheatsheet_file": "cheatsheets/python-basics/python_cheatsheet_days_01_30.pdf",
        "cheatsheet_page": day,
        "project": {
            "title": f"Мини-проект дня: {title}",
            "goal": practice,
            "file_name": project_file,
            "run_command": run_command,
            "steps": (
                "Создайте отдельную папку дня и указанный файл проекта.",
                "Наберите код с экрана вручную и после каждой строки объясните её действие.",
                "Сохраните файл, запустите его из терминала и сравните вывод с ожидаемым.",
                "Измените одно входное значение, заранее предскажите новый результат и запустите снова.",
                "Добавьте один граничный или ошибочный случай и убедитесь, что понимаете поведение программы.",
            ),
            "result": f"Готовый проект выполняет задачу: {practice} Вы можете показать его работу и объяснить связь с темой «{title}».",
        },
        "checkpoint": _checkpoint(question, answers, correct, explanation),
        "code": code.strip(),
        "code_title": "Рабочий пример Python",
    }


